  async createSequenceEnrollment(enrollment: InsertSequenceEnrollment): Promise<typeof sequenceEnrollments.$inferSelect | null> {
    // Wrap the status-check + insert in a single transaction and lock the
    // sequence row FOR UPDATE.  This closes the race window where a sequence
    // could be paused between the status SELECT and the enrollment INSERT,
    // which would silently create an active enrollment in a paused sequence.
    return await db.transaction(async (tx) => {
      if (enrollment.sequenceId) {
        // SELECT FOR UPDATE prevents any concurrent UPDATE (e.g. pause) from
        // committing until our transaction finishes.
        const seqRows = await tx.execute(
          sql`SELECT status FROM follow_up_sequences WHERE id = ${enrollment.sequenceId} AND retired_at IS NULL FOR UPDATE`
        );
        const seqStatus = (seqRows.rows[0] as any)?.status;
        if (!seqStatus) {
          throw new Error(`Sequence ${enrollment.sequenceId} not found — enrollment blocked.`);
        }
        if (seqStatus !== "active") {
          throw new Error(`Sequence ${enrollment.sequenceId} is ${seqStatus} — enrollment blocked. Activate the sequence before enrolling contacts.`);
        }
      }

      // Idempotency check — prevent TOCTOU double-enrollment.
      // If an active or paused enrollment already exists for this contact+sequence,
      // skip the insert and return null. The partial unique index
      // (idx_sequence_enrollments_active_unique) is a hard DB backstop; this
      // pre-check avoids the constraint violation in the happy path.
      if (enrollment.contactId && enrollment.sequenceId) {
        const [existing] = await tx
          .select({ id: sequenceEnrollments.id })
          .from(sequenceEnrollments)
          .where(
            and(
              eq(sequenceEnrollments.contactId, enrollment.contactId),
              eq(sequenceEnrollments.sequenceId, enrollment.sequenceId),
              inArray(sequenceEnrollments.status, ["active", "paused"])
            )
          )
          .limit(1);
        if (existing) {
          // C-13 (#1626): route direct audit inserts through the canonical sanitizer
          await tx.insert(auditLogs).values({
            action: "sequence_enrollment_duplicate_skipped",
            entityType: "contact",
            entityId: enrollment.contactId,
            actorType: "system",
            details: (await import("../services/audit-sanitizer")).sanitizeAuditPayload({
              contactId: enrollment.contactId,
              sequenceId: enrollment.sequenceId,
              existingEnrollmentId: existing.id,
              reason: "Active or paused enrollment already exists — duplicate insert skipped.",
            }),
          } as any);
          return null;
        }
      }

      try {
        const [created] = await tx.insert(sequenceEnrollments).values(enrollment).returning();
        return created;
      } catch (err: any) {
        // Catch any DB unique-constraint violation from the partial index (hard backstop).
        // Treat it as a skip — do not rethrow so callers never crash.
        const isUniqueViolation =
          err?.code === "23505" ||
          (typeof err?.message === "string" && err.message.includes("idx_sequence_enrollments_active_unique"));
        if (isUniqueViolation) {
          if (enrollment.contactId && enrollment.sequenceId) {
            // C-13 (#1626): route direct audit inserts through the canonical sanitizer
            await tx.insert(auditLogs).values({
              action: "sequence_enrollment_duplicate_skipped",
              entityType: "contact",
              entityId: enrollment.contactId,
              actorType: "system",
              details: (await import("../services/audit-sanitizer")).sanitizeAuditPayload({
                contactId: enrollment.contactId,
                sequenceId: enrollment.sequenceId,
                reason: "DB unique constraint violation caught — duplicate insert blocked by index.",
              }),
            } as any);
          }
          return null;
        }
        throw err;
      }
    });
  }


  async updateSequenceEnrollment(id: number, updates: Partial<InsertSequenceEnrollment>) {
    const coercedUpdates = coerceDateFields(
      updates as Record<string, unknown>,
      ["nextActionAt", "completedAt", "pausedAt"],
    );
    const [updated] = await db.update(sequenceEnrollments).set({ ...coercedUpdates, updatedAt: new Date() } as typeof sequenceEnrollments.$inferInsert).where(eq(sequenceEnrollments.id, id)).returning();
    return updated;
  }


  async cancelSequenceEnrollment(sequenceId: number, contactId: number): Promise<typeof sequenceEnrollments.$inferSelect | null> {
    const [enrollment] = await db
      .select()
      .from(sequenceEnrollments)
      .where(
        and(
          eq(sequenceEnrollments.sequenceId, sequenceId),
          eq(sequenceEnrollments.contactId, contactId),
          inArray(sequenceEnrollments.status, ["active", "paused"])
        )
      )
      .limit(1);
    if (!enrollment) return null;
    const [updated] = await db
      .update(sequenceEnrollments)
      .set({ status: "cancelled", updatedAt: new Date() })
      .where(eq(sequenceEnrollments.id, enrollment.id))
      .returning();
    return updated ?? null;
  }


  async getActiveEnrollments() {
    const now = new Date();
    return await db.select().from(sequenceEnrollments).where(
      and(
        eq(sequenceEnrollments.status, "active"),
        sql`${sequenceEnrollments.nextActionAt} IS NOT NULL`,
        sql`${sequenceEnrollments.nextActionAt} <= ${now}`
      )
    );
  }

  async pauseAllActiveEnrollments(contactId: number): Promise<number> {
    const active = await db.select({ id: sequenceEnrollments.id })
      .from(sequenceEnrollments)
      .where(
        and(
          eq(sequenceEnrollments.contactId, contactId),
          eq(sequenceEnrollments.status, "active")
        )
      );
    if (active.length === 0) return 0;
    await db.update(sequenceEnrollments)
      .set({ status: "paused", pausedAt: new Date(), updatedAt: new Date() })
      .where(
        and(
          eq(sequenceEnrollments.contactId, contactId),
          eq(sequenceEnrollments.status, "active")
        )
      );
    return active.length;
  }

  async getContactEnrollmentsForContacts(contactIds: number[], sequenceIds?: number[]) {
    if (contactIds.length === 0) return [];
    const CHUNK = 500;
    const results: typeof sequenceEnrollments.$inferSelect[] = [];
    for (let i = 0; i < contactIds.length; i += CHUNK) {
      const chunk = contactIds.slice(i, i + CHUNK);
      const condition = sequenceIds && sequenceIds.length > 0
        ? and(inArray(sequenceEnrollments.contactId, chunk), inArray(sequenceEnrollments.sequenceId, sequenceIds))
        : inArray(sequenceEnrollments.contactId, chunk);
      const rows = await db.select().from(sequenceEnrollments).where(condition);
      results.push(...rows);
    }
    return results;
  }

  async getFollowUpSequencesByIds(sequenceIds: number[]) {
    if (sequenceIds.length === 0) return [];
    const CHUNK = 500;
    const results: typeof followUpSequences.$inferSelect[] = [];
    for (let i = 0; i < sequenceIds.length; i += CHUNK) {
      const chunk = sequenceIds.slice(i, i + CHUNK);
      const rows = await db.select().from(followUpSequences).where(inArray(followUpSequences.id, chunk));
      results.push(...rows);
    }
    return results;
  }

  async getSequenceStepsForSequences(sequenceIds: number[]) {
    if (sequenceIds.length === 0) return [];
    const CHUNK = 500;
    const results: typeof sequenceSteps.$inferSelect[] = [];
    for (let i = 0; i < sequenceIds.length; i += CHUNK) {
      const chunk = sequenceIds.slice(i, i + CHUNK);
      const rows = await db.select().from(sequenceSteps)
        .where(inArray(sequenceSteps.sequenceId, chunk))
        .orderBy(asc(sequenceSteps.stepOrder));
      results.push(...rows);
    }
    return results;
  }

